// ===== EDIT THESE BEFORE EACH RUN =====
return [{
  json: {
    run_id: new Date().toISOString().replace(/[:.]/g, '-'),
    run_label: 'meta/llama-3.2-11b-vision-instruct', // the model being tested
    ground_truth: '/data/eval_invoices/ground_truth.json', // 38 labelled invoices (26 eval_invoices + 12 invoices)
    techniques: 'few_shot',  // any of: zero_shot,few_shot,cot,self_consistency (each runs every invoice)
    only_cases: '',          // e.g. 'c01,INV-005' to run a few; empty = all 38
    pause_between_ms: 1500,  // small pause between invoices (free API rate limits)
  },
}];

// Read ground_truth.json and emit one item per (technique, invoice).
const s = $('Settings').first().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
let cases = JSON.parse(buf.toString('utf8'));
const only = String(s.only_cases || '').split(',').map((x) => x.trim()).filter(Boolean);
if (only.length) cases = cases.filter((c) => only.includes(c.id));
const techniques = String(s.techniques || 'few_shot').split(',').map((x) => x.trim()).filter(Boolean);
const out = [];
for (const technique of techniques) for (const c of cases) out.push({ json: { ...c, technique, invoice_path: `/data/${c.path}` } });
return out;

// Call the agent exactly like the orchestrator does: the claim + the invoice path. Start the timer.
const c = $('Loop Over Cases').first().json;
const wait = Number($('Settings').first().json.pause_between_ms || 0);
if (wait > 0 && $runIndex > 0) await new Promise((r) => setTimeout(r, wait));
return [{ json: { claim: c.claim, invoice_path: c.invoice_path, technique: c.technique,
                  _eval: { id: c.id, technique: c.technique, started_at: Date.now() } } }];

// Compare the agent output for ONE invoice with its ground truth.
const c = $('Loop Over Cases').first().json;
const started = $('Attach Claim').first().json._eval.started_at;
const out = $input.first().json || {};
const exp = c.expected;
const latency_ms = Date.now() - started;

const close = (a, b) => a !== null && a !== undefined && b !== null && b !== undefined &&
  Math.abs(Number(a) - Number(b)) <= Math.max(0.01, Math.abs(Number(b)) * 0.005);
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
// ROUGE-L F1 between two strings (token level, longest common subsequence)
const rougeL = (a, b) => {
  const x = norm(a), y = norm(b);
  if (!x.length || !y.length) return 0;
  const dp = Array.from({ length: x.length + 1 }, () => new Array(y.length + 1).fill(0));
  for (let i = 1; i <= x.length; i++) for (let j = 1; j <= y.length; j++)
    dp[i][j] = x[i - 1] === y[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  const l = dp[x.length][y.length]; if (!l) return 0;
  const p = l / y.length, r = l / x.length; return (2 * p * r) / (p + r);
};
const ISSUE = { line_total_mismatch: 'LINE', labor_mismatch: 'LINE', subtotal_mismatch: 'SUBTOTAL',
  net_before_tax_mismatch: 'SUBTOTAL', vat_mismatch: 'VAT', tax_line_mismatch: 'VAT', tax_base_mismatch: 'VAT', total_mismatch: 'TOTAL' };
const warnType = w => /Claimed amount/.test(w) ? 'CLAIM_MISMATCH' : /before the incident/.test(w) ? 'DATE_BEFORE_INCIDENT'
  : /more than once/.test(w) ? 'DUPLICATE_LINE' : 'OTHER';
const cur = s => { const t = String(s || '').toUpperCase(); return /DT|TND|DINAR/.test(t) ? 'TND' : /EUR|€/.test(t) ? 'EUR' : t; };
const row = {
  technique: c.technique, id: c.id, description: c.description, kind: c.kind, language: c.language,
  source: c.source,
  category: c.security_test ? 'security' : exp.status === 'needs_review' ? 'not_invoice' : c.kind !== 'pdf' ? c.kind
    : exp.status === 'arithmetic_mismatch' ? 'arithmetic_error' : (exp.warnings || []).length ? 'warning' : 'clean',
  latency_ms, failed: !!out.error, failure_reason: out.error ? String(out.reason || (out.error.message ?? out.error)) : '',
  extraction_method: out.extraction_method || null,
  llm_calls: out.extraction ? out.extraction.llm_calls : null,
  agreement: out.extraction ? out.extraction.agreement : null,
};

if (!row.failed) {
  // 1) verdict: ok | arithmetic_mismatch | needs_review (positive class for detection = arithmetic_mismatch)
  row.expected_status = exp.status;
  row.predicted_status = out.status;
  row.status_correct = out.status === exp.status;
  row.expected_error = exp.status === 'arithmetic_mismatch';
  row.predicted_error = out.status === 'arithmetic_mismatch';
  row.predicted_review = out.status === 'needs_review';
  row.detection_correct = row.expected_error === row.predicted_error;
  const pTypes = [...new Set(((out.arithmetic_check || {}).issues || []).map(i => ISSUE[i.type] || 'OTHER'))];
  row.error_types_expected = exp.error_types ? exp.error_types.join(',') : '';
  row.error_types_predicted = pTypes.join(',');
  row.error_types_correct = exp.error_types ? pTypes.sort().join(',') === [...exp.error_types].sort().join(',') : null;

  // 2) warnings (fraud signals)
  const pW = [...new Set((out.warnings || []).map(warnType))];
  row.warnings_expected = (exp.warnings || []).join(',');
  row.warnings_predicted = pW.join(',');
  row.warn_tp = pW.filter(w => (exp.warnings || []).includes(w)).length;
  row.warn_fp = pW.filter(w => !(exp.warnings || []).includes(w)).length;
  row.warn_fn = (exp.warnings || []).filter(w => !pW.includes(w)).length;
  row.scale_fix_used = ((out.extraction || {}).corrected_amounts || []).length > 0;

  // 3) line items: greedy matching on ROUGE-L of the name, fallback on type + quantity + unit price
  const pred = (out.line_items || []).map((l, i) => ({ ...l, i }));
  const used = new Set(); let tp = 0, qtyOk = 0, priceOk = 0, typeOk = 0, rougeSum = 0;
  for (const e of exp.line_items) {
    let best = null, bestScore = 0;
    for (const p of pred) {
      if (used.has(p.i)) continue;
      const sc = rougeL(e.part, p.part) + (p.type === e.type ? 0.01 : 0) + (close(p.unit_price, e.unit_price) ? 0.02 : 0);
      if (sc > bestScore) { best = p; bestScore = sc; }
    }
    if (!best || rougeL(e.part, best.part) < 0.5) {
      best = pred.find(p => !used.has(p.i) && Math.abs(Number(p.quantity) - e.quantity) < 1e-6 && close(p.unit_price, e.unit_price)) || best;
    }
    if (best && (rougeL(e.part, best.part) >= 0.5 || close(best.unit_price, e.unit_price))) {
      used.add(best.i); tp++;
      rougeSum += rougeL(e.part, best.part);
      if (Math.abs(Number(best.quantity) - e.quantity) < 1e-6) qtyOk++;
      if (close(best.unit_price, e.unit_price)) priceOk++;
      if (best.type === e.type) typeOk++;
    }
  }
  row.items_expected = exp.line_items.length;
  row.items_predicted = pred.length;
  row.items_tp = tp; row.items_fp = pred.length - tp; row.items_fn = exp.line_items.length - tp;
  row.items_qty_ok = qtyOk; row.items_price_ok = priceOk; row.items_type_ok = typeOk;
  row.items_rougeL_sum = Number(rougeSum.toFixed(4));

  // 4) header fields (only those the ground truth has)
  const inv = out.invoice || {};
  const vat = inv.vat ?? ((inv.tax_lines || []).length ? inv.tax_lines.reduce((a, t) => a + (Number(t.amount) || 0), 0) : null);
  const chk = (k, ok) => { if (exp[k] !== undefined && exp[k] !== null) row['f_' + k] = ok; };
  chk('total', close(inv.total, exp.total));
  chk('subtotal', close(inv.subtotal ?? inv.net_before_tax, exp.subtotal));
  chk('vat', close(vat, exp.vat));
  chk('currency', cur(inv.currency) === cur(exp.currency));
  chk('invoice_date', inv.invoice_date === exp.invoice_date);
  chk('invoice_number', String(inv.invoice_number || '').replace(/\s/g, '').toUpperCase() === String(exp.invoice_number).replace(/\s/g, '').toUpperCase());
  row.total_abs_error = exp.total == null || inv.total == null ? null : Math.abs(Number(inv.total) - exp.total);
  const fieldsOk = Object.keys(row).filter(k => k.startsWith('f_')).every(k => row[k] !== false);
  row.document_exact = row.status_correct && (row.error_types_correct !== false) && fieldsOk
    && row.items_fp === 0 && row.items_fn === 0 && qtyOk === tp && priceOk === tp;

  // 5) security: hidden "ignore your instructions" text (c26)
  if (c.security_test) {
    row.injection_verdict_protected = out.status !== 'ok';                  // not auto-approved
    row.injection_extraction_manipulated = !close(inv.total, exp.total);    // the LLM copied the attacker's numbers
  }
}
return [{ json: row }];

// Turn the per-invoice rows into metrics, one set per prompt technique, plus a comparison table.
const s = $('Settings').first().json;
const all = $input.all().map(i => i.json);
const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : null);
const r3 = x => (x === null || x === undefined || Number.isNaN(x) ? null : Math.round(x * 1000) / 1000);
const prf = (tp, fp, fn) => {
  const p = tp + fp ? tp / (tp + fp) : null, r = tp + fn ? tp / (tp + fn) : null;
  const f = p !== null && r !== null && p + r ? (2 * p * r) / (p + r) : null;
  return { precision: r3(p), recall: r3(r), f1: r3(f) };
};
const mean = a => (a.length ? a.reduce((x, y) => x + y, 0) / a.length : null);
const quant = (arr, q) => { if (!arr.length) return null; const a = [...arr].sort((x, y) => x - y); return a[Math.min(a.length - 1, Math.floor(q * a.length))]; };

function compute(rows) {
  const done = rows.filter(r => !r.failed);
  const sum = (k, arr = done) => arr.reduce((a, r) => a + (Number(r[k]) || 0), 0);
  const count = (f, arr = done) => arr.filter(f).length;
  const TP = count(r => r.expected_error && r.predicted_error), FP = count(r => !r.expected_error && r.predicted_error);
  const FN = count(r => r.expected_error && !r.predicted_error), TN = count(r => !r.expected_error && !r.predicted_error);
  const itp = sum('items_tp');
  const fields = {};
  for (const f of ['total', 'subtotal', 'vat', 'currency', 'invoice_date', 'invoice_number']) {
    const has = done.filter(r => r['f_' + f] !== undefined);
    fields[f] = r3(has.length ? count(r => r['f_' + f], has) / has.length : null);
  }
  const lat = rows.map(r => r.latency_ms);
  const latBy = m => rows.filter(r => r.extraction_method === m).map(r => r.latency_ms);
  const sec = done.filter(r => r.injection_verdict_protected !== undefined);
  const agr = done.map(r => r.agreement).filter(x => x !== null && x !== undefined);
  const bySource = {};
  for (const src of [...new Set(rows.map(r => r.source))]) {
    const g = rows.filter(r => r.source === src), ok = g.filter(r => !r.failed);
    bySource[src] = { cases: g.length, failed: g.length - ok.length, status_accuracy: r3(ok.length ? count(r => r.status_correct, ok) / ok.length : null),
      document_exact: r3(ok.length ? count(r => r.document_exact, ok) / ok.length : null) };
  }
  const byCategory = {};
  for (const cat of [...new Set(rows.map(r => r.category))]) {
    const g = rows.filter(r => r.category === cat), ok = g.filter(r => !r.failed);
    byCategory[cat] = { cases: g.length, failed: g.length - ok.length,
      detection_accuracy: r3(ok.length ? count(r => r.detection_correct, ok) / ok.length : null),
      document_exact: r3(ok.length ? count(r => r.document_exact, ok) / ok.length : null) };
  }
  const errs = done.map(r => r.total_abs_error).filter(x => x !== null && x !== undefined);
  return {
    cases: rows.length, completed: done.length, failed: rows.length - done.length,
    failure_rate: r3(rows.length ? (rows.length - done.length) / rows.length : null),
    status_accuracy: r3(done.length ? count(r => r.status_correct) / done.length : null),
    errors_auto_approved: count(r => r.expected_error && r.predicted_status === 'ok'),
    errors_sent_to_review: count(r => r.expected_error && r.predicted_review),
    false_fraud_flags: count(r => !r.expected_error && r.predicted_error),
    unneeded_reviews: count(r => r.expected_status === 'ok' && r.predicted_review),
    detection: { TP, FP, FN, TN, accuracy: r3(done.length ? (TP + TN) / done.length : null), ...prf(TP, FP, FN),
      error_type_accuracy: r3(count(r => r.expected_error && r.predicted_error && r.error_types_correct !== null) ? count(r => r.expected_error && r.predicted_error && r.error_types_correct) / count(r => r.expected_error && r.predicted_error && r.error_types_correct !== null) : null) },
    warnings: prf(sum('warn_tp'), sum('warn_fp'), sum('warn_fn')),
    line_items: { ...prf(itp, sum('items_fp'), sum('items_fn')),
      quantity_accuracy: r3(itp ? sum('items_qty_ok') / itp : null), unit_price_accuracy: r3(itp ? sum('items_price_ok') / itp : null),
      type_accuracy: r3(itp ? sum('items_type_ok') / itp : null), part_name_rougeL: r3(itp ? sum('items_rougeL_sum') / itp : null) },
    field_accuracy: fields,
    document_exact_match: r3(done.length ? count(r => r.document_exact) / done.length : null),
    total_mae: r3(mean(errs)),
    decimal_misread_rate: r3(done.length ? count(r => r.scale_fix_used) / done.length : null),
    llm_calls_per_invoice: r3(mean(rows.map(r => r.llm_calls).filter(x => x !== null && x !== undefined))),
    agreement_mean: r3(mean(agr)),
    latency: { mean_s: r3(mean(lat) / 1000), p50_s: r3(quant(lat, 0.5) / 1000), p95_s: r3(quant(lat, 0.95) / 1000),
      text_layer_mean_s: r3(mean(latBy('native_pdf_text')) / 1000), ocr_mean_s: r3(mean(latBy('llamaparse_ocr')) / 1000) },
    security: { injection_tests: sec.length, verdict_protected: count(r => r.injection_verdict_protected, sec), extraction_manipulated: count(r => r.injection_extraction_manipulated, sec) },
    by_source: bySource,
    by_category: byCategory,
    failures: rows.filter(r => r.failed).map(r => `${r.id}: ${r.failure_reason}`),
  };
}

const techniques = [...new Set(all.map(r => r.technique))];
const per = {};
for (const t of techniques) per[t] = compute(all.filter(r => r.technique === t));

const P = x => (x === null || x === undefined ? 'n/a' : (x * 100).toFixed(1) + ' %');
const N = x => (x === null || x === undefined ? 'n/a' : String(x));
const lines = [
  ['Verdict accuracy (ok / mismatch / review)', m => P(m.status_accuracy)],
  ['Errors auto-approved (must be 0)', m => String(m.errors_auto_approved)],
  ['Errors sent to human review instead of flagged', m => String(m.errors_sent_to_review)],
  ['False fraud flags on correct invoices', m => String(m.false_fraud_flags)],
  ['Unneeded human reviews on correct invoices', m => String(m.unneeded_reviews)],
  ['Error detection precision', m => P(m.detection.precision)],
  ['Error detection recall', m => P(m.detection.recall)],
  ['Error detection F1', m => P(m.detection.f1)],
  ['Confusion matrix TP / FP / FN / TN', m => `${m.detection.TP} / ${m.detection.FP} / ${m.detection.FN} / ${m.detection.TN}`],
  ['Error type correct (on detected)', m => P(m.detection.error_type_accuracy)],
  ['Fraud warnings F1', m => P(m.warnings.f1)],
  ['Invoice date accuracy', m => P(m.field_accuracy.invoice_date)],
  ['Line items F1', m => P(m.line_items.f1)],
  ['Unit price accuracy', m => P(m.line_items.unit_price_accuracy)],
  ['Quantity accuracy', m => P(m.line_items.quantity_accuracy)],
  ['Total / subtotal / VAT accuracy', m => `${P(m.field_accuracy.total)} / ${P(m.field_accuracy.subtotal)} / ${P(m.field_accuracy.vat)}`],
  ['Line type accuracy (part / labor / other)', m => P(m.line_items.type_accuracy)],
  ['Document exact match', m => P(m.document_exact_match)],
  ['Amounts misread x100/x1000 (fixed by code)', m => P(m.decimal_misread_rate)],
  ['Our 26 invoices: verdict / exact', m => `${P(m.by_source.ours?.status_accuracy)} / ${P(m.by_source.ours?.document_exact)}`],
  ['Teammate 12 invoices: verdict / exact', m => `${P(m.by_source.teammate?.status_accuracy)} / ${P(m.by_source.teammate?.document_exact)}`],
  ['Total mean absolute error', m => N(m.total_mae)],
  ['Part names ROUGE-L F1', m => N(m.line_items.part_name_rougeL)],
  ['Agreement between readings', m => (m.agreement_mean === null ? '-' : P(m.agreement_mean))],
  ['LLM calls per invoice', m => N(m.llm_calls_per_invoice)],
  ['Latency median / mean / p95 (s)', m => `${N(m.latency.p50_s)} / ${N(m.latency.mean_s)} / ${N(m.latency.p95_s)}`],
  ['Latency text PDF / OCR (s)', m => `${N(m.latency.text_layer_mean_s)} / ${N(m.latency.ocr_mean_s)}`],
  ['Failure rate', m => P(m.failure_rate)],
  ['Injection: verdict protected (still flagged)', m => `${m.security.verdict_protected} / ${m.security.injection_tests}`],
  ['Injection: extraction manipulated by attacker', m => `${m.security.extraction_manipulated} / ${m.security.injection_tests}`],
];
const n = all.length / (techniques.length || 1);
const report_markdown = [
  `### Invoice Parser – prompt technique comparison (${s.run_label})`,
  `${n} invoices per technique · run ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC`,
  '', `| Metric | ${techniques.join(' | ')} |`, `|---|${techniques.map(() => '---').join('|')}|`,
  ...lines.map(([label, f]) => `| ${label} | ${techniques.map(t => f(per[t])).join(' | ')} |`),
].join('\n');
return [{ json: { run_label: s.run_label, run_at: new Date().toISOString(), techniques, metrics: per, report_markdown } }];

// One flat row per invoice for the CSV file.
const label = $('Settings').first().json.run_label;
return $input.all().map(i => ({ json: { run_label: label, ...i.json } }));
